(()=>{
 const hero=document.querySelector('#home'),about=document.querySelector('#about');
 const shell=document.createElement('div');shell.className='entrance-sequence';hero.before(shell);shell.append(hero,about);
 const clamp=x=>Math.max(0,Math.min(1,x));let scheduled=false;
 function update(){scheduled=false;hero.style.setProperty('--hero-top',`${Math.min(0,innerHeight-hero.offsetHeight)}px`);const r=about.getBoundingClientRect(),p=clamp((innerHeight-r.top)/innerHeight),enabled=!paused;shell.style.setProperty('--entrance-progress',enabled?p:0);hero.style.setProperty('--entrance-lift',enabled?`${p*-70}px`:'0px');hero.style.setProperty('--entrance-scale',enabled?1-p*.045:1);hero.style.setProperty('--entrance-opacity',enabled?1-p*.32:1);about.style.setProperty('--context-x',enabled?`${(1-p)*70}px`:'0px');about.style.setProperty('--context-inset',enabled?`${(1-p)*6}%`:'0%');about.style.setProperty('--context-opacity',enabled?.5+p*.5:1);about.style.setProperty('--context-radius',enabled?`${(1-p)*55}px`:'0px');about.style.setProperty('--context-slide',enabled?`${(1-p)*55}px`:'0px');}
 function schedule(){if(!scheduled){scheduled=true;requestAnimationFrame(update)}}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);document.querySelector('#motion').addEventListener('click',schedule);update();
 const observer=new IntersectionObserver(entries=>entries.forEach(({target,isIntersecting})=>{if(isIntersecting){target.classList.add('arrived');observer.unobserve(target)}}),{threshold:.12});
 function watchCards(){document.querySelectorAll('.award-card').forEach((card,i)=>{card.classList.add('scroll-piece');card.style.setProperty('--piece-delay',`${i%3*65}ms`);observer.observe(card)})}
 const baseSelect=selectCategory;selectCategory=function(id){baseSelect(id);document.querySelector('#detail-dialog').dataset.theme=id;watchCards()};watchCards();
 document.querySelectorAll('.life-card').forEach(card=>{card.classList.add('scroll-piece');observer.observe(card)});
 // Sound is synthesized locally, only after a deliberate click; no autoplay or network audio.
 let audio,sound=true;const toggle=document.querySelector('#sound-toggle');try{sound=localStorage.getItem('vrajesh-sound')!=='off'}catch{}
 function soundUI(){toggle.setAttribute('aria-pressed',String(sound));toggle.setAttribute('aria-label',sound?'Mute click sounds':'Enable click sounds');toggle.querySelector('span').textContent=sound?'on':'off'}soundUI();
 toggle.onclick=()=>{sound=!sound;try{localStorage.setItem('vrajesh-sound',sound?'on':'off')}catch{}soundUI()};
 async function play(certificate){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')await audio.resume();const now=audio.currentTime;const length=certificate?.055:.035;const buffer=audio.createBuffer(1,Math.ceil(audio.sampleRate*length),audio.sampleRate);const samples=buffer.getChannelData(0);for(let i=0;i<samples.length;i++){const t=i/samples.length;samples[i]=(Math.random()*2-1)*Math.exp(-t*11)}const source=audio.createBufferSource(),filter=audio.createBiquadFilter(),volume=audio.createGain();source.buffer=buffer;filter.type='lowpass';filter.frequency.value=certificate?1350:1050;volume.gain.value=certificate?.075:.055;source.connect(filter);filter.connect(volume);volume.connect(audio.destination);source.start(now);}catch{}}
 document.addEventListener('click',event=>{const target=event.target.closest('button,a');if(!target||target.disabled)return;play(target.hasAttribute('data-award')||target.id==='next-award'||target.id==='previous-award')});
})();
